"UPNODE" VARCHAR2(100 BYTE) NULL ,
"CACHE" VARCHAR2(10 BYTE) DEFAULT '1'  NULL ,
"SJDJ" VARCHAR2(10 BYTE) DEFAULT '3'  NULL 
)
LOGGING
NOCOMPRESS
NOCACHE

;
COMMENT ON TABLE "SJSJ"."SYS_SJGL_TYZD" IS '系统-数据管理-统一字典';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."ID" IS '主键';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."CJSJ" IS '创建时间';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."GXSJ" IS '更新时间';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."YXX" IS '有效性@SYS_COMMON_LJPD';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."PX" IS '排序;建议排序都按10、20、30的方式排序，方便修改穿插';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."KZXX" IS '扩展信息;JSON格式';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."CJRXM" IS '创建人姓名';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."CJRDM" IS '创建人代码@SYS_COMMON_USER';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."CJRDWMC" IS '创建人单位名称';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."CJRDWDM" IS '创建人单位代码@SYS_COMMON_ORG';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."DM" IS '代码';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."MC" IS '名称';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."MS" IS '描述';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."JP" IS '简拼';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."QP" IS '全拼';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."ZDLB" IS '字典类别';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."BZZD" IS '标准字典;用于数据标准化等场景，如性别可以有几套字典，然后关联一个标准字典,进一步通过mc关联';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."LBSQL" IS '类别SQL;当次SQL为空时，字典默认在此统一字典表中，有SQL则通过SQL获取字典';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."SJLY" IS '数据来源';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."UPNODE" IS '父节点';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."CACHE" IS '是否缓存';
COMMENT ON COLUMN "SJSJ"."SYS_SJGL_TYZD"."SJDJ" IS '数据等级';

